def admit_calendar_steps_source(source, owner_sources, shared_message_source):
    """Complete source/AST admission, not native or dynamic acceptance."""
    tree = ast.parse(source)
    if ast.dump(tree, include_attributes=False) != EXPECTED_MODULE_AST:
        raise ValueError('complete finite calendar graph differs from its admitted module')
    shared = next((ast.literal_eval(node.value) for node in tree.body if isinstance(node, ast.Assign) and any((isinstance(target, ast.Name) and target.id == 'CALENDAR_SHARED_MESSAGE_AST' for target in node.targets))))
    if ast.dump(ast.parse(shared_message_source), include_attributes=False) != shared:
        raise ValueError('complete explicit current shared message source required')
    constants = {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1 and isinstance(node.targets[0], ast.Name) and (node.targets[0].id in ('VIEW_SPECS', 'EXPECTED_SOURCE', 'EXPECTED_SYNCHRONOUS_SOURCE')):
            constants[node.targets[0].id] = ast.literal_eval(node.value)
    if set(owner_sources) != set(constants['EXPECTED_SOURCE']):
        raise ValueError('all three actual calendar source modules required')
    namespace = dict(ast=ast, copy=copy, VIEW_SPECS=constants['VIEW_SPECS'], EXPECTED_SOURCE=constants['EXPECTED_SOURCE'])
    definitions = [node for node in tree.body if isinstance(node, ast.FunctionDef) and node.name in ('_dump', '_cooperative_module')]
    if len(definitions) != 2:
        raise ValueError('complete admitted calendar inverse utilities required')
    exec(compile(ast.Module(body=definitions, type_ignores=[]), '<calendar source-only inverse>', 'exec'), namespace)
    for group, expected in constants['EXPECTED_SOURCE'].items():
        original = ast.parse(owner_sources[group])
        combined = dict(constants['EXPECTED_SYNCHRONOUS_SOURCE'].get(group, {}))
        combined.update(expected)
        nodes = {node.name: node for node in original.body if isinstance(node, ast.FunctionDef)}
        for name, text in combined.items():
            if name not in nodes or ast.dump(nodes[name], include_attributes=False) != ast.dump(ast.parse(text).body[0], include_attributes=False):
                raise ValueError('complete calendar owner source differs: ' + name)
        namespace['_cooperative_module'](group, original)
    return dict(source_only=True, complete_module_inverse=True, formal_credit=0, game=False, normal_API=False, native=False, strict_pending_unchanged=46004)
